function() {
    if ($(this).val()) {
        $(this).addClass("hasText");
    } else {
        $(this).removeClass("hasText");
    }
    if (!$(this).val()) {
        $(this).parent().parent().parent().parent().addClass("error");
        return false;
    } else {
        $(this).parent().parent().parent().parent().removeClass("error");
    }
}

